export interface LogoPart {
  /** رقم الجزء في الشعار (حرف أو نقطة أو الريشة). */
  id: number;
  /** شكل الجزء الكامل (fill-rule: evenodd). */
  d: string;
}

export interface PenStroke {
  /** الجزء اللي الخط ده بيكشفه. */
  part: number;
  /** مسار الخط في الوسط (وحدات الـ viewBox) — بيترسم كـ mask. */
  d: string;
  /** سُمك الـ mask عشان يغطي عرض الحرف. */
  width: number;
  delay: number;
  duration: number;
  /** نفس المسار بالبكسل لحركة الريشة (offset-path)، أو null للخطوط القصيرة. */
  pen: string | null;
}

export interface MotifStroke {
  d: string;
  delay: number;
}

